mapper.select:
SELECT r.*, p.name AS project_name, v.release_label AS version_label
FROM requirements r
LEFT JOIN api_projects p             ON p.code = r.project_code
LEFT JOIN release_version_archives v ON v.id   = r.version_id

    AND r.project_code = #{projectCode}
    AND r.version_id = #{versionId}
    AND r.status = #{status}

        AND (r.requirement_no LIKE CONCAT('%', #{keyword}, '%')
          OR r.title LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY r.updated_at DESC, r.requirement_no DESC
